import java.io.*;
import java.util.*;

public class CutletVariant4 {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] firstLine = br.readLine().split(" ");
        int n = Integer.parseInt(firstLine[0]);
        int k = Integer.parseInt(firstLine[1]);
        int[][] segments = new int[k][2];

        for (int i = 0; i < k; i++) {
            String[] line = br.readLine().split(" ");
            segments[i][0] = Integer.parseInt(line[0]);
            segments[i][1] = Integer.parseInt(line[1]);
        }

        Arrays.sort(segments, (a, b) -> a[0] - b[0]);

        List<int[]> mergedSegments = new ArrayList<>();
        int idx = 0;
        while (idx < k) {
            int start = segments[idx][0];
            int end = segments[idx][0];
            int j = idx;
            while (j < k && segments[j][0] <= end) {
                end = Math.max(end, segments[j][1]);
                j++;
            }
            mergedSegments.add(new int[]{start, end});
            idx = j;
        }

        k = mergedSegments.size();
        int[] lengths = new int[k];
        int[] deltas = new int[k];
        int[][] segs = new int[k][2];

        for (int i = 0; i < k; i++) {
            segs[i] = mergedSegments.get(i);
        }

        for (int i = 0; i < k; i++) {
            lengths[i] = segs[i][1] - segs[i][0];
            if (i < k - 1) {
                deltas[i] = segs[i + 1][0] - segs[i][1];
            } else {
                deltas[i] = 2 * n - segs[i][1];
            }
        }

        int[][][] dp = new int[2][k + 1][2 * n + 1];
        for (int[][] layer : dp) {
            for (int[] row : layer) {
                Arrays.fill(row, n);
            }
        }

        dp[0][k][n] = 0;
        dp[1][k][n] = 0;

        RMQ[] rmqArr = {new RMQ(dp[0][k]), new RMQ(dp[1][k])};

        for (int i = k - 1; i >= 0; i--) {
            for (int j = 0; j <= 2 * n; j++) {
                int val0 = (j + lengths[i] + deltas[i] <= 2 * n) ? dp[0][i + 1][j + lengths[i] + deltas[i]] : n;
                int val1 = dp[1][i + 1][j];

                dp[0][i][j] = Math.min(val0, 1 + rmqArr[1].min(j, Math.min(j + lengths[i], 2 * n)));
                if (j + deltas[i] <= 2 * n) {
                    int candidate1 = 1 + rmqArr[0].min(j + deltas[i], Math.min(j + lengths[i] + deltas[i], 2 * n));
                    dp[1][i][j] = Math.min(val1, candidate1);
                } else {
                    dp[1][i][j] = val1;
                }

                if (j + deltas[i] <= 2 * n) {
                    int candidate2 = 2 + rmqArr[0].min(j + deltas[i], Math.min(j + lengths[i] + deltas[i], 2 * n));
                    dp[0][i][j] = Math.min(dp[0][i][j], candidate2);
                }

                int candidate3 = 2 + rmqArr[1].min(j, Math.min(j + lengths[i], 2 * n));
                dp[1][i][j] = Math.min(dp[1][i][j], candidate3);
            }
            rmqArr[0] = new RMQ(dp[0][i]);
            rmqArr[1] = new RMQ(dp[1][i]);
        }

        int answer = dp[1][0][0];
        if (answer == n) {
            System.out.println("Hungry");
        } else {
            System.out.println("Full");
            System.out.println(answer);
        }
    }

    static class RMQ {
        int size, log;
        int[][] sparse;

        public RMQ(int[] array) {
            size = array.length;
            log = Integer.numberOfTrailingZeros(Integer.highestOneBit(size)) + 1;
            sparse = new int[log][size];
            System.arraycopy(array, 0, sparse[0], 0, size);
            for (int i = 1; i < log; i++) {
                for (int j = 0; j + (1 << i - 1) < size; j++) {
                    sparse[i][j] = Math.min(sparse[i - 1][j], sparse[i - 1][j + (1 << i - 1)]);
                }
            }
        }

        public int min(int a, int b) {
            int length = b - a + 1;
            int z = Integer.numberOfTrailingZeros(Integer.highestOneBit(length));
            return Math.min(sparse[z][a], sparse[z][b - (1 << z) + 1]);
        }
    }
}
